<?php

namespace Wallacemartinss\FilamentIconPicker\Enums;

use Filament\Support\Contracts\ScalableIcon;
use Filament\Support\Enums\IconSize;

/**
 * Icon enum for filament
 *
 * Generated by Filament Icon Picker
 *
 * @see https://github.com/wallacemartinss/filament-icon-picker
 */
enum Filament: string implements ScalableIcon
{
    case FiMPencilSlash = 'fi-m-pencil-slash';
    case FiOAlignCenter = 'fi-o-align-center';
    case FiOAlignEnd = 'fi-o-align-end';
    case FiOAlignJustify = 'fi-o-align-justify';
    case FiOAlignStart = 'fi-o-align-start';
    case FiOArrowsMove = 'fi-o-arrows-move';
    case FiOClearFormatting = 'fi-o-clear-formatting';
    case FiOCode = 'fi-o-code';
    case FiOCodeBlock = 'fi-o-code-block';
    case FiOColumns = 'fi-o-columns';
    case FiOColumnsDelete = 'fi-o-columns-delete';
    case FiOCrop = 'fi-o-crop';
    case FiODetails = 'fi-o-details';
    case FiOFlipHorizontal = 'fi-o-flip-horizontal';
    case FiOFlipVertical = 'fi-o-flip-vertical';
    case FiOH1 = 'fi-o-h1';
    case FiOH2 = 'fi-o-h2';
    case FiOH3 = 'fi-o-h3';
    case FiOH4 = 'fi-o-h4';
    case FiOH5 = 'fi-o-h5';
    case FiOH6 = 'fi-o-h6';
    case FiOHeading = 'fi-o-heading';
    case FiOHighlight = 'fi-o-highlight';
    case FiOLead = 'fi-o-lead';
    case FiOMergeTag = 'fi-o-merge-tag';
    case FiOParagraph = 'fi-o-paragraph';
    case FiOSmall = 'fi-o-small';
    case FiOSubscript = 'fi-o-subscript';
    case FiOSuperscript = 'fi-o-superscript';
    case FiOTable = 'fi-o-table';
    case FiOTableAddColumnAfter = 'fi-o-table-add-column-after';
    case FiOTableAddColumnBefore = 'fi-o-table-add-column-before';
    case FiOTableAddRowAfter = 'fi-o-table-add-row-after';
    case FiOTableAddRowBefore = 'fi-o-table-add-row-before';
    case FiOTableDelete = 'fi-o-table-delete';
    case FiOTableDeleteColumn = 'fi-o-table-delete-column';
    case FiOTableDeleteRow = 'fi-o-table-delete-row';
    case FiOTableMergeCells = 'fi-o-table-merge-cells';
    case FiOTableSplitCell = 'fi-o-table-split-cell';
    case FiOTableToggleHeaderCell = 'fi-o-table-toggle-header-cell';
    case FiOTableToggleHeaderRow = 'fi-o-table-toggle-header-row';

    /**
     * Get the icon name for the given size.
     */
    public function getIconForSize(IconSize $size): string
    {
        return $this->value;
    }

    /**
     * Get the icon name as a string.
     */
    public function toString(): string
    {
        return $this->value;
    }

    /**
     * Get all available icons.
     *
     * @return array<string, string>
     */
    public static function options(): array
    {
        return array_column(self::cases(), 'value', 'name');
    }

    /**
     * Search for icons by name.
     *
     * @return array<self>
     */
    public static function search(string $query): array
    {
        return array_filter(
            self::cases(),
            fn (self $icon) => str_contains(strtolower($icon->name), strtolower($query))
        );
    }
}
